#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Run from app/ no matter where the script is invoked from.
cd "$(dirname "$0")/.."
ENV_FILE=".env.deploy"   # non-secret values only (gitignored via .env.*); secrets go straight to Cloudflare
WR="npx wrangler"

# set_wrangler_var KEY VALUE: fill the FIRST (top-level, app worker) occurrence of "KEY": "..." in wrangler.jsonc.
set_wrangler_var() {
  node -e '
    const fs=require("fs"),[k,v]=process.argv.slice(1);
    const p="wrangler.jsonc",s=fs.readFileSync(p,"utf8");
    const needle="\""+k+"\"", i=s.indexOf(needle);
    if(i<0){console.error("key not found: "+k);process.exit(1)}
    const q1=s.indexOf("\"",s.indexOf(":",i+needle.length)), q2=s.indexOf("\"",q1+1);
    fs.writeFileSync(p,s.slice(0,q1+1)+v+s.slice(q2));' "$1" "$2"
  printf '  %s✓ set%s %s in wrangler.jsonc
' "$GREEN" "$RESET" "$1"
}
# put_secret NAME VALUE [--env bot]: pipe a secret into Cloudflare, never to disk.
put_secret() {
  local name="$1" value="$2"; shift 2
  (( $# )) || set -- --env=""
  printf '%s' "$value" | $WR secret put "$name" "$@" >/dev/null
  printf '  %s✓ secret%s %s %s\n' "$GREEN" "$RESET" "$name" "${*:-(training)}"
}

TOTAL_STAGES=9

banner "Training app: deploy to Cloudflare + Telegram"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Cloudflare"
say "Wrangler opens your browser so you can allow it to manage your Cloudflare account."
step "Click 'Allow' on the Cloudflare page that opens, then come back here."
$WR login
$WR whoami | sed 's/^/  /'
pause "Signed in as the right account? Press Enter."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the database"
say "Creating a D1 database called 'training' (skipped if it already exists)."
$WR d1 create training >/dev/null 2>&1 || note "(already exists, reusing it)"
D1_ID=$($WR d1 list --json | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const db=JSON.parse(s).find(d=>d.name==="training");process.stdout.write(db?db.uuid:"")})')
[[ -n "$D1_ID" ]] || { warn "couldn't find the 'training' database"; exit 1; }
# node, not `sed -i`: BSD sed on macOS reads -i's next argument as a backup suffix.
node -e 'const fs=require("fs"),p="wrangler.jsonc";fs.writeFileSync(p,fs.readFileSync(p,"utf8").split("REPLACE_AFTER_d1_create").join(process.argv[1]))' "$D1_ID"
write_env D1_ID "$D1_ID"
say "Applying the schema. Wrangler asks you to confirm; answer y."
$WR d1 migrations apply training --remote

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "First deploy (both Workers)"
say "Deploying 'training' (tracker, API, reminders) and 'training-bot' (Telegram webhook only)."
$WR deploy --env=""
$WR deploy --env bot
note "Each deploy above printed its https://….workers.dev address."
ask APP_URL "Paste the 'training' URL (https://training.<you>.workers.dev):"
ask BOT_URL "Paste the 'training-bot' URL (https://training-bot.<you>.workers.dev):"
APP_URL="${APP_URL%/}"; BOT_URL="${BOT_URL%/}"
write_env APP_URL "$APP_URL"
write_env BOT_URL "$BOT_URL"
note "If Wrangler asked you to register a workers.dev subdomain, pick any name you like."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Telegram bot token"
say "Create your own bot with BotFather (or reuse one you already have)."
open_url "https://t.me/BotFather"
step "In BotFather, send /newbot. Pick a display name, then a username that ends in 'bot'."
step "BotFather replies with the bot's HTTP API token. (Existing bot: /mybots → your bot → API Token.)"
ask BOT_USERNAME "Your bot's username (without the @):"
BOT_USERNAME="${BOT_USERNAME#@}"
until [[ "$BOT_USERNAME" =~ ^[A-Za-z0-9_]{5,32}$ ]]; do
  ask BOT_USERNAME "That doesn't look like a bot username (5-32 letters, digits or _). Try again:"
  BOT_USERNAME="${BOT_USERNAME#@}"
done
write_env BOT_USERNAME "$BOT_USERNAME"
ask_secret TG_TOKEN "Paste the bot token (hidden):"
until curl -fsS "https://api.telegram.org/bot${TG_TOKEN}/getMe" | grep -q '"ok":true'; do
  warn "Telegram rejected that token."
  ask_secret TG_TOKEN "Paste the bot token again (hidden):"
done
note "Token works."
put_secret TELEGRAM_BOT_TOKEN "$TG_TOKEN"
put_secret TELEGRAM_BOT_TOKEN "$TG_TOKEN" --env bot

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Your Telegram chat ID"
say "The app only ever talks to your own chat. Reading it from your 'hi' message."
get_chat_id() {
  { curl -fsS "https://api.telegram.org/bot${TG_TOKEN}/getUpdates" || echo '{}'; } | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const u=(JSON.parse(s).result||[]).reverse().find(x=>x.message&&x.message.chat&&x.message.chat.type==="private");process.stdout.write(u?String(u.message.chat.id):"")})'
}
# getUpdates answers 409 while a webhook is set (a re-run); stage 6 sets it again.
curl -fsS "https://api.telegram.org/bot${TG_TOKEN}/deleteWebhook" >/dev/null || true
CHAT_ID=$(get_chat_id)
while [[ -z "$CHAT_ID" ]]; do
  open_url "https://t.me/${BOT_USERNAME}"
  step "Send the bot any message (e.g. 'hi'), then press Enter."
  pause
  CHAT_ID=$(get_chat_id)
done
say "Found chat ID $CHAT_ID."
write_env TELEGRAM_CHAT_ID "$CHAT_ID"
put_secret TELEGRAM_CHAT_ID "$CHAT_ID"
put_secret TELEGRAM_CHAT_ID "$CHAT_ID" --env bot

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Connect Telegram to the bot Worker"
WEBHOOK_SECRET=$(node -e 'process.stdout.write(require("crypto").randomBytes(32).toString("hex"))')
put_secret TELEGRAM_WEBHOOK_SECRET "$WEBHOOK_SECRET" --env bot
RES=$(curl -fsS -X POST "https://api.telegram.org/bot${TG_TOKEN}/setWebhook" \
  --data-urlencode "url=${BOT_URL}/telegram/webhook" \
  --data-urlencode "secret_token=${WEBHOOK_SECRET}" \
  --data-urlencode 'allowed_updates=["message","callback_query"]')
grep -q '"ok":true' <<<"$RES" && note "Webhook set → ${BOT_URL}/telegram/webhook" || { warn "setWebhook failed: $RES"; exit 1; }
unset WEBHOOK_SECRET

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Lock the tracker behind your email (Cloudflare Access)"
say "One-click Access puts an email-code login in front of the 'training' Worker only."
open_url "https://dash.cloudflare.com/?to=/:account/workers/services/view/training/production/settings"
step "Settings → Domains & Routes → on the workers.dev row (and Preview URLs) click 'Enable Cloudflare Access'."
step "If asked to create a Zero Trust team, pick a team name; the Free plan is fine."
step "The modal shows POLICY_AUD and TEAM_DOMAIN. Keep it open."
step "Click 'Manage Cloudflare Access' and check the policy allows your email."
step "In that Access application's settings (Advanced / Cookie settings), set SameSite to Lax if offered."
warn "Do NOT enable Access on 'training-bot'. Telegram must be able to reach it."
ask ACCESS_AUD "Paste POLICY_AUD:"
ask ACCESS_TEAM_DOMAIN "Paste TEAM_DOMAIN (e.g. https://yourteam.cloudflareaccess.com):"
ACCESS_TEAM_DOMAIN="${ACCESS_TEAM_DOMAIN#https://}"; ACCESS_TEAM_DOMAIN="${ACCESS_TEAM_DOMAIN%/}"
write_env ACCESS_AUD "$ACCESS_AUD"
write_env ACCESS_TEAM_DOMAIN "$ACCESS_TEAM_DOMAIN"
set_wrangler_var ACCESS_AUD "$ACCESS_AUD"
set_wrangler_var ACCESS_TEAM_DOMAIN "$ACCESS_TEAM_DOMAIN"
say "Redeploying the tracker with the Access settings."
$WR deploy --env="" >/dev/null && note "Redeployed."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Connect your watch (intervals.icu)"
say "intervals.icu (free) collects your watch Activities; the app reads them with your personal API key."
open_url "https://intervals.icu"
step "Sign up or log in at intervals.icu."
step "Settings → Connections: connect your watch's own service (Garmin Connect, Coros, Suunto, Polar, Wahoo…)."
note "Strava-imported Activities are not passed on to other apps, so connect the watch service directly."
step "Settings → Developer Settings → API key: generate one and copy it."
ICU_OK=""
while [[ -z "$ICU_OK" ]]; do
  ask_secret ICU_KEY "Paste the intervals.icu API key (hidden, Enter to skip):"
  if [[ -z "$ICU_KEY" ]]; then
    confirm "Skip intervals.icu? Watch Activities won't be credited until you add it." && break
    continue
  fi
  # The key goes to curl on stdin (-K -), never in its argv.
  CODE=$(printf 'user = "API_KEY:%s"\n' "$ICU_KEY" | curl -sS -K - -o /dev/null -w '%{http_code}' "https://intervals.icu/api/v1/athlete/0" || true)
  case "$CODE" in
    200) ICU_OK=1 ;;
    401|403) warn "intervals.icu rejected that key." ;;
    *) warn "Couldn't reach intervals.icu (HTTP ${CODE:-none}). Check your internet connection and try again." ;;
  esac
done
if [[ -n "$ICU_OK" ]]; then
  note "Key works."
  put_secret INTERVALS_API_KEY "$ICU_KEY"   # app Worker only: the bot never syncs
else
  SKIPPED+=("intervals.icu: npx wrangler secret put INTERVALS_API_KEY --env=\"\"")
fi
unset ICU_KEY

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Smoke test"
open_url "$APP_URL"
step "The tracker asks for your email, then a one-time code. Sign in."
step "Today tab loads with no red banner. More › Test Week → start a Test Week, or enter your TM Test results."
[[ -n "$ICU_OK" ]] && step "Progress › Recent Activities → Sync now. Your recent watch Activities appear in the list."
pause "Tracker OK? Press Enter."
open_url "https://t.me/${BOT_USERNAME}"
step "Send /today to the bot. It should answer with today's plan and buttons."
pause "Bot answered? Press Enter."
unset TG_TOKEN

finish
note "App:  $APP_URL"
note "Bot:  $BOT_URL (webhook only)"
note "Reminders: 07:00 brief, 21:30 mobility, Sunday 19:00 preview (local time)."
